#include <hip/hip_runtime.h>
#include <stdint.h>
__global__ __launch_bounds__(32) void occupancy_control(float* out, int64_t iterations) {
  const int i = blockIdx.x * blockDim.x + threadIdx.x;
  float v = float(i + 1) * 0.000001f;
  for (int64_t n = 0; n < iterations; ++n) {
    v = __fmaf_rn(v, 0.999999f, 0.000001f);
    v = __fmaf_rn(v, 0.999998f, 0.000002f);
    v = __fmaf_rn(v, 0.999997f, 0.000003f);
    v = __fmaf_rn(v, 0.999996f, 0.000004f);
  }
  out[i] = v;
}
extern "C" hipError_t launch_occupancy_control(void* out, int64_t iterations, int64_t blocks) {
 hipLaunchKernelGGL(occupancy_control,dim3(blocks),dim3(32),0,0,static_cast<float*>(out),iterations);
 return hipGetLastError();
}
